 detail=await api(state.people[0],'/sports/rooms/'+state.roomA);check('recruitment joins only after invitation confirmation',detail.members.length===2);
 if(!state.roomB){const first=await action(state.people[2],'room.match',{unitId:state.pairUnit,timePreference:'any'});check('automatic matching waits for a compatible participant',first.state==='waiting'||first.status==='waiting');const offer=await action(state.people[3],'room.match',{unitId:state.pairUnit,timePreference:'any'});state.autoOffer=offer.offerId;save();await action(state.people[2],'room.answer',{offerId:state.autoOffer,answer:'accept'});const joined=await action(state.people[3],'room.answer',{offerId:state.autoOffer,answer:'accept'});state.roomB=joined.roomId;save();}
