 if(!state.roomExpiry){const a=await action(state.people[4],'room.match',{unitId:state.pairUnit});const b=await action(state.people[5],'room.match',{unitId:state.pairUnit});state.expiredOffer=b.offerId;sql(`UPDATE asp_matching_offer SET expires_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE id=${state.expiredOffer};`);const expired=await request(state.people[4],'/sports/platform/actions/room.answer/execute','POST',{input:{offerId:state.expiredOffer,answer:'accept'},requestKey:crypto.randomUUID()});check('expired offers cannot be accepted',expired.code!==200);await action(state.people[4],'room.stopMatch',{requestId:a.requestId});const mine=await api(state.people[5],'/sports/rooms');if(mine.requests[0])await action(state.people[5],'room.stopMatch',{requestId:mine.requests[0].id});state.roomExpiry=true;save();}
 for(const [room,indexes,key] of [[state.roomA,[0,1],'entryA'],[state.roomB,[2,3],'entryB']]){if(state[key])continue;for(const i of indexes){const d=await api(state.people[i],'/sports/rooms/'+room);await action(state.people[i],'room.ready',{roomId:room,ready:true,expectedVersion:Number(d.room.version)});}const d=await api(state.people[indexes[0]],'/sports/rooms/'+room);check('readiness is individually confirmed',d.members.every(m=>m.ready));const host=state.people.find(p=>p.id===d.room.host_account_id);assert.ok(host,'Room has an accountable host');const entry=await action(host,'room.prepare',{roomId:room,expectedVersion:Number(d.room.version)});state[key]=entry.registrationId;save();}
