 const count=Number(sql("SELECT count(*) FROM asp_file WHERE purpose='ai-source';"));const denied=await upload(state.people[0],null,false,[{body,name:'规程.docx'}]);check('generic material upload requires current DeepSeek consent before storage',denied.code!==200&&Number(sql("SELECT count(*) FROM asp_file WHERE purpose='ai-source';"))===count);
 if(!state.materialRun){const value=await upload(state.people[0],null,true,[{body,name:'规程文件.pdf'}]);assert.equal(value.code,200,'Content-signature upload accepts DOCX despite a different extension');state.materialRun=value.data.runId;save();}
 let run;for(let i=0;i<40;i++){run=await api(state.people[0],'/sports/agents/runs/'+state.materialRun);if(run.status!=='running')break;await new Promise(r=>setTimeout(r,250));}assert.equal(run.status,'failed');assert.equal(run.stopReason,'KEY_ABSENT');const sources=run.messages.flatMap(m=>JSON.parse(m.blocks)).filter(b=>b.kind==='material');check('generic assistant saves file hash, paragraph locations, scope and goal when model key is absent',sources.some(b=>b.format==='docx'&&b.locations.includes('段落1')&&b.sha256===crypto.createHash('sha256').update(body).digest('hex'))&&run.messages.some(m=>m.content.includes('当前页面对象')));
